def fibonacci(n):
    """Calculates the nth Fibonacci number iteratively."""
    if n <= 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def is_prime(num):
    """Checks if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def sum_first_n_primes(n):
    """Calculates the sum of the first n prime numbers."""
    primes_sum = 0
    count = 0
    current_num = 2

    while count < n:
        if is_prime(current_num):
            primes_sum += current_num
            count += 1
        current_num += 1
    return primes_sum

if __name__ == "__main__":
    # Compute 25th Fibonacci number
    # F(0)=0, F(1)=1, ..., F(25)
    fib_25 = fibonacci(25)

    # Compute sum of first 100 prime numbers
    sum_100_primes = sum_first_n_primes(100)

    print(f"The 25th Fibonacci number (F(25)) is: {fib_25}")
    print(f"The sum of the first 100 prime numbers is: {sum_100_primes}")
```

